export const getGenerateQRCodeUrl = (params?: GenerateQRCodeParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/v1/qrcode?${stringifiedParams}` : `/v1/qrcode`
}

/**
 * @summary Create QR Code
 */
export const generateQRCode = async (params?: GenerateQRCodeParams, options?: Parameters<typeof apiFetch>[1]): Promise<Blob> => {

  return apiFetch<Blob>(getGenerateQRCodeUrl(params),
  {
    ...options,
    method: 'GET'


  }
);}





